    if v1 == v2:
        return v1 * t

    if abs(v1 - v2) > d * (t - 1):
        return -1

    if v1 < v2:
        increasing_speeds = [v1 + i * d for i in range(t)]
        decreasing_speeds = [v1 + i * d for i in range(t-1, -1, -1)]
        return sum(increasing_speeds[:-1]) + sum(decreasing_speeds[1:])

