def max_path_length(v1, v2, t, d):
    if v1 == v2:
        return v1 * t

    max_speed = max(v1, v2)
    min_speed = min(v1, v2)
    steps = t - 1

    if abs(v1 - v2) <= d:
        return (v1 + v2) * (t // 2) + (steps % 2) * min(abs(v1 - v2), d)

    increase_count = (max_speed - v1) // d
    decrease_count = (v2 - min_speed) // d

    if increase_count + decrease_count >= steps:
        return max_speed * (steps // 2) + (steps % 2) * min(max_speed - v1, d)
    else:
        remaining_steps = steps - (increase_count + decrease_count)
        return (v1 + max_speed) * (increase_count + remaining_steps // 2) + (remaining_steps % 2) * min(d, max_speed - v1)

